apiVersion: networking.k8s.io/v1
kind: NetworkPolicy
metadata:
  name: proof-restic
spec:
  podSelector:
    matchLabels:
      app.kubernetes.io/name: proof-restic
  policyTypes: [Ingress]
  ingress:
    - ports:
        - protocol: TCP
          port: 8443

