apiVersion: apps/v1
kind: Deployment
metadata:
  name: proof-restic
spec:
  replicas: 1
  strategy:
    type: Recreate
  selector:
    matchLabels:
      app.kubernetes.io/name: proof-restic
  template:
    metadata:
      labels:
        app.kubernetes.io/name: proof-restic
      annotations:
        checksum/config: a3607093881276e16d8a9676bb9596756b7e6786738e8802f79c31dfac0ba5f9
    spec:
      automountServiceAccountToken: false
      initContainers:
        - name: require-initialized-repositories
          image: docker.io/library/nginx:1.28.0
          command: [/bin/sh, -ec]
          args:
            - |
              test -s /data/alpha/config || { echo 'Repository alpha is missing its config; initialize it explicitly before deployment' >&2; exit 1; }
              for directory in data index keys locks snapshots; do
                test -d /data/alpha/"$directory" || { echo "Repository alpha is missing $directory" >&2; exit 1; }
              done
              test -s /data/beta/config || { echo 'Repository beta is missing its config; initialize it explicitly before deployment' >&2; exit 1; }
              for directory in data index keys locks snapshots; do
                test -d /data/beta/"$directory" || { echo "Repository beta is missing $directory" >&2; exit 1; }
              done
          volumeMounts:
            - name: data
              mountPath: /data
              readOnly: true
      containers:
        - name: writer
          image: docker.io/restic/rest-server@sha256:d2aff06f47eb38637dff580c3e6bce4af98f386c396a25d32eb6727ec96214a5
          command: [rest-server]
          args: [--path, /data, --listen, '127.0.0.1:8000', --no-auth, --append-only]
          volumeMounts:
            - name: data
              mountPath: /data
        - name: repository
          image: docker.io/restic/rest-server@sha256:d2aff06f47eb38637dff580c3e6bce4af98f386c396a25d32eb6727ec96214a5
          command: [rest-server]
          args: [--path, /data, --listen, '127.0.0.1:8001', --no-auth]
          volumeMounts:
            - name: data
              mountPath: /data
        - name: https
          image: docker.io/library/nginx:1.28.0
          ports:
            - name: https
              containerPort: 8443
          readinessProbe:
            tcpSocket:
              port: https
          volumeMounts:
            - name: nginx
              mountPath: /etc/nginx/nginx.conf
              subPath: nginx.conf
              readOnly: true
            - name: tls
              mountPath: /tls
              readOnly: true
            - name: auth-alpha
              mountPath: /auth/alpha
              readOnly: true
            - name: auth-beta
              mountPath: /auth/beta
              readOnly: true
      volumes:
        - name: data
          persistentVolumeClaim:
            claimName: "repositories"
        - name: nginx
          configMap:
            name: proof-restic
        - name: tls
          secret:
            secretName: "repository-tls"
        - name: auth-alpha
          secret:
            secretName: "alpha-auth"
            items:
              - key: htpasswd
                path: htpasswd
        - name: auth-beta
          secret:
            secretName: "beta-auth"
            items:
              - key: htpasswd
                path: htpasswd

